if($guild){echo '<section class="comm-card"><h4>Dynamic Territory Events</h4><p>Celestial anomalies reduce production and may improve defensive stability. Pirate invasions threaten territory output and require a coordinated response.</p><div class="admin-table-wrap"><table><tr><th>Event</th><th>Territory</th><th>Severity</th><th>Effect</th><th>Response</th><th>Ends</th><th>Action</th></tr>';if($events)while($e=$events->fetch_assoc())echo '<tr><td>'.guild_h(ucwords(str_replace('_',' ',(string)$e['event_type']))).'</td><td>#'.(int)$e['territory_id'].'</td><td>'.(int)$e['severity'].'/5</td><td>'.(int)$e['effect_percent'].'% production penalty</td><td>'.(int)$e['response_power'].' / '.((int)$e['severity']*100).'</td><td>'.guild_h($e['ends_at']).'</td><td><form method="post" action="modules/guild.php?time='.time().'" class="inline-form"><input type="hidden" name="csrf" value="'.guild_h($csrf).'"/><input type="hidden" name="guild_action" value="respond_event"/><input type="hidden" name="event_id" value="'.(int)$e['event_id'].'"/><input type="number" name="response_power" min="1" max="1000" value="100"/><button class="comm-btn">Respond</button></form></td></tr>';echo '</table></div></section><section class="comm-card"><h4>Guild Technology Tree</h4><div class="admin-table-wrap"><table><tr><th>Technology</th><th>Level</th><th>Effect</th><th>Action</th></tr>';foreach(GuildResearchPolicy::tree() as $key=>$node){$level=(int)($researchLevels[$key]??0);echo '<tr><td>'.guild_h($node['name']).'</td><td>'.$level.'/'.GuildResearchPolicy::MAX_LEVEL.'</td><td>Production +'.$node['production'].'% · Military +'.$node['military'].'% · Defense +'.$node['defense'].'%</td><td>'.(GuildPolicy::can($rank,'start_research')&&$level<GuildResearchPolicy::MAX_LEVEL?'<form method="post" action="modules/guild.php?time='.time().'" class="inline-form"><input type="hidden" name="csrf" value="'.guild_h($csrf).'"/><input type="hidden" name="guild_action" value="research"/><input type="hidden" name="tech_key" value="'.guild_h($key).'"/><button class="comm-btn">Research</button></form>':'Locked').'</td></tr>';}echo '</table></div></section><section class="comm-card guild-warfare-card"><div class="guild-warfare-head"><div><span class="rts-kicker">CORPORATE DIPLOMACY // FRONTIER WARFARE</span><h4>Diplomacy and Warfare</h4><p>Alliance proposals, war declarations, and raids are governed by rank permissions and server-side ownership checks.</p></div><div class="guild-warfare-badge">SECURE COMMAND LINK</div></div><div class="guild-warfare-grid"><div class="guild-warfare-status"><h5>Alliance Network</h5><div class="admin-table-wrap"><table><tr><th>Relation</th><th>Counterparty</th><th>Status</th></tr>';if($diplomacy)while($d=$diplomacy->fetch_assoc()){$counter=(int)$d['guild_low_id']===$guildId?(int)$d['guild_high_id']:(int)$d['guild_low_id'];echo '<tr><td>'.guild_h(ucfirst((string)$d['relation'])).'</td><td>Guild #'.$counter.'</td><td><span class="guild-status guild-status-ally">ACTIVE</span></td></tr>';}echo '</table></div></div><div class="guild-warfare-status"><h5>Active Warfronts</h5><div class="admin-table-wrap"><table><tr><th>War</th><th>Opponent</th><th>Ends</th></tr>';if($wars)while($w=$wars->fetch_assoc()){$opponent=(int)$w['attacker_guild_id']===$guildId?(int)$w['defender_guild_id']:(int)$w['attacker_guild_id'];echo '<tr><td>#'.(int)$w['war_id'].'</td><td>Guild #'.$opponent.'</td><td>'.guild_h($w['ends_at']).'</td></tr>';}echo '</table></div></div></div><div class="guild-warfare-actions"><form method="post" action="modules/guild.php?time='.time().'" class="inline-form"><input type="hidden" name="csrf" value="'.guild_h($csrf).'"/><input type="hidden" name="guild_action" value="propose_alliance"/><input type="number" name="target_guild_id" min="1" placeholder="Target Guild ID" required><button class="comm-btn">Alliance</button></form><form method="post" action="modules/guild.php?time='.time().'" class="inline-form"><input type="hidden" name="csrf" value="'.guild_h($csrf).'"/><input type="hidden" name="guild_action" value="declare_war"/><input type="number" name="target_guild_id" min="1" placeholder="Target Guild ID" required><button class="comm-btn">Declare War</button></form><form method="post" action="modules/guild.php?time='.time().'" class="inline-form"><input type="hidden" name="csrf" value="'.guild_h($csrf).'"/><input type="hidden" name="guild_action" value="launch_raid"/><input type="number" name="target_territory_id" min="1" placeholder="Enemy Territory ID" required><input type="number" name="attack_power" min="1" max="'.GuildWarfarePolicy::MAX_RAID_POWER.'" placeholder="Attack Power" required><button class="comm-btn">Launch Raid</button></form></div></section>';}echo '</div>'; $pagegen->stop(); print('page generation time: '.$pagegen->gen()); ?>
